package vn.edu.eaut.lab8.bean; import jakarta.enterprise.context.SessionScoped; import jakarta.inject.Named; import jakarta.faces.application.FacesMessage; import jakarta.faces.context.FacesContext; import vn.edu.eaut.lab8.model.SanPham; import java.io.Serializable; import java.util.*; @Named("productBean") @SessionScoped public class ProductBean implements Serializable { private List<SanPham> ds=new ArrayList<>();private SanPham sp=new SanPham();private int next=1;public String save(){sp.setId(next++);ds.add(sp);msg("Thành công","Đã lưu sản phẩm");sp=new SanPham();return null;}public List<SanPham>getDs(){return ds;}public SanPham getSp(){return sp;}public void setSp(SanPham x){sp=x;}private void msg(String a,String b){FacesContext.getCurrentInstance().addMessage(null,new FacesMessage(FacesMessage.SEVERITY_INFO,a,b));}}
